# Impact artifacts contain portable name@version keys, never checkout-local IDs.
# Resolve those keys against workspace members on the runner executing the check.
function Get-AnvilPackages {
    param([string] $Scope = '--workspace', [string[]] $Toolchain = @())

    if ($Scope -eq '--skip') { return }
    $json = & cargo @Toolchain metadata --locked --no-deps --format-version 1
    if ($LASTEXITCODE -ne 0) { throw "anvil: cargo metadata failed (exit $LASTEXITCODE)" }
    $metadata = $json | ConvertFrom-Json -ErrorAction Stop
    if ($null -eq $metadata.workspace_members -or $null -eq $metadata.packages) {
        throw 'anvil: cargo metadata omitted workspace package identity'
    }
    $members = @($metadata.packages | Where-Object { $metadata.workspace_members -ccontains $_.id })
    foreach ($member in $members) {
        $member | Add-Member -NotePropertyName anvil_workspace_root -NotePropertyValue $metadata.workspace_root
    }
    if (-not $Scope -or $Scope -eq '--workspace') { return $members }

    $tokens = @(-split $Scope)
    if ($tokens.Count % 2 -ne 0) { throw "anvil: invalid package scope '$Scope'" }
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    for ($i = 0; $i -lt $tokens.Count; $i += 2) {
        if ($tokens[$i] -notin @('--package', '-p')) { throw "anvil: invalid package scope '$Scope'" }
        $key = $tokens[$i + 1]
        $matches = @($members | Where-Object { $_.name -ceq $key -or "$($_.name)@$($_.version)" -ceq $key })
        if ($matches.Count -ne 1) { throw "anvil: package '$key' must resolve to exactly one workspace member" }
        if ($seen.Add($matches[0].id)) { $matches[0] }
    }
}

function Get-AnvilPackageArguments {
    param(
        [object[]] $Packages,
        [ValidateSet('cargo', 'manifest', 'semver', 'llvm-cov', 'each', 'names')]
        [string] $Adapter = 'cargo'
    )

    if ($Adapter -eq 'semver') {
        if ($Packages.Count -ne 1) { throw 'anvil: semver requires exactly one package' }
        '--manifest-path'
        $Packages[0].manifest_path
        # semver-checks matches workspace names, not Cargo package ID specs.
        Get-AnvilPackageArguments -Packages $Packages -Adapter names
        return
    }
    if ($Adapter -eq 'manifest' -and $Packages.Count -eq 1) {
        '--manifest-path'
        $Packages[0].manifest_path
        # A root package's manifest also selects workspace default-members.
        # Keep explicit single-package requests isolated in that case.
        if ((Split-Path -Parent $Packages[0].manifest_path) -eq $Packages[0].anvil_workspace_root) {
            Get-AnvilPackageArguments -Packages $Packages -Adapter cargo
        }
        return
    }
    foreach ($package in $Packages) {
        '--package'
        switch ($Adapter) {
            'names' { $package.name }
            'each' { "$($package.name)@$($package.version)" }
            'llvm-cov' { $package.id }
            default {
                # Cargo accepts source-qualified specs; unlike llvm-cov's literal
                # metadata-ID matcher it does not need the metadata source kind.
                ([string]$package.id) -replace '^path\+', ''
            }
        }
    }
}

function Resolve-AnvilPackageArguments {
    param(
        [string] $Scope = '--workspace',
        [string[]] $Toolchain = @(),
        [string] $Adapter = 'manifest'
    )

    if (-not $Scope -or $Scope -eq '--workspace') { '--workspace'; return }
    $packages = @(Get-AnvilPackages -Scope $Scope -Toolchain $Toolchain)
    Get-AnvilPackageArguments -Packages $packages -Adapter $Adapter
}
